-- Immutable snapshot from Drive source اصناف_النظام_السابق.xlsx (read 2026-11-03).
-- Source: المعرف -> items.legacy_id; المبيعات_مرات_في_سنة -> sale_times.
-- 15253 source IDs; only 4680 positive values imported. 10453 zeros and 120 blanks implicitly mean zero.
-- Never calculate this value from subsequent sales and never update item master revisions.
-- Company 2 is the pharmacy. Rows belong to the legacy ID, even if the item has not been imported yet.
CREATE TABLE IF NOT EXISTS company_item_previous_year_sale_times (
  company_id integer NOT NULL REFERENCES companies(id) ON DELETE CASCADE,
  legacy_id text NOT NULL CHECK (length(legacy_id) BETWEEN 1 AND 100),
  sale_times integer NOT NULL CHECK (sale_times >= 1),
  PRIMARY KEY (company_id,legacy_id)
);
CREATE INDEX IF NOT EXISTS item_previous_year_sale_times_filter_idx
  ON company_item_previous_year_sale_times(company_id,sale_times,legacy_id)
  WHERE sale_times >= 1;
